SELECT p.*, CASE WHEN import_quantity_t > 0 AND import_value_usd IS NOT NULL THEN import_value_usd / NULLIF(import_quantity_t,0) END AS reported_import_unit_value_usd_t, CASE WHEN export_quantity_t > 0 AND export_value_usd IS NOT NULL THEN export_value_usd / NULLIF(export_quantity_t,0) END AS reported_export_unit_value_usd_t FROM (SELECT f.year_key, f.reporter_geography_key, f.partner_geography_key, f.product_key, MAX(CASE WHEN t.source_metric_id='5610' THEN f.value END) AS import_quantity_t, count_if(t.source_metric_id='5610') AS present_5610, MAX(CASE WHEN t.source_metric_id='5610' THEN f.observation_key END) AS observation_5610, MAX(CASE WHEN t.source_metric_id='5622' THEN f.value END) AS import_value_usd, count_if(t.source_metric_id='5622') AS present_5622, MAX(CASE WHEN t.source_metric_id='5622' THEN f.observation_key END) AS observation_5622, MAX(CASE WHEN t.source_metric_id='5910' THEN f.value END) AS export_quantity_t, count_if(t.source_metric_id='5910') AS present_5910, MAX(CASE WHEN t.source_metric_id='5910' THEN f.observation_key END) AS observation_5910, MAX(CASE WHEN t.source_metric_id='5922' THEN f.value END) AS export_value_usd, count_if(t.source_metric_id='5922') AS present_5922, MAX(CASE WHEN t.source_metric_id='5922' THEN f.observation_key END) AS observation_5922 FROM {{fact_fao_trade_observation}} f JOIN {{dim_observation_type}} t ON f.observation_type_key=t.observation_type_key GROUP BY f.year_key, f.reporter_geography_key, f.partner_geography_key, f.product_key) p
